function openReplay(){if(!state.submitted)return;if(handsUI)handsUI.cancel();cancelStir();pause();replayIndex=0;$('recipeReplayJump').replaceChildren();renderReplay();if(scene&&!textView)scene.view('bench');$('recipeReplayControls').focus();$('recipeReplayControls').scrollIntoView({block:'start'});}
function closeReplay(){replayIndex=null;renderReplay();if(scene&&!textView)scene.view('plate');$('openRecipeReplay').focus();}
$('openRecipeReplay').addEventListener('click',openReplay);$('reviewReplay').addEventListener('click',openReplay);$('closeRecipeReplay').addEventListener('click',closeReplay);
$('recipeReplayStep').addEventListener('input',function(){replayIndex=Number(this.value);renderReplay();});$('recipeReplayJump').addEventListener('change',function(){replayIndex=Number(this.value);renderReplay();});
$('recipeReplayPrevious').addEventListener('click',function(){replayIndex=Math.max(0,replayIndex-1);renderReplay();});$('recipeReplayNext').addEventListener('click',function(){replayIndex=Math.min(state.log.length,replayIndex+1);renderReplay();});
