$('recipePlan').addEventListener('input',function(){state.plan=this.value;save();});$('recipeReflection').addEventListener('input',function(){state.reflection=this.value;save();});
document.querySelectorAll('input[name=reason0]').forEach(function(input){input.addEventListener('change',function(){state.answers[0]=Number(input.value);render(false);save();});});
